import type { Client } from '../spec/client'

/**
 * A runtime plugin for the client generated by `@hey-api/openapi-ts`.
 *
 * The generated client (0.99) has no plugin array, so plugins install themselves
 * as interceptors on its middleware.
 */
export interface ApiClientPlugin {
  install(client: Client): void
}

/** Installs each plugin into the client, in order. */
export function installApiClientPlugins(client: Client, plugins: ApiClientPlugin[]): Client {
  for (const plugin of plugins) plugin.install(client)
  return client
}
